# Surah At-Tawbah (chapter 9) — part 4: ayat 31-40 (IDs 1266-1275)
SURAH = 9

ENTRIES = {
1266: (
"انہوں نے — اپنے — احبار و رہبان — کو — اللہ کے علاوہ — رب — بنا لیا — اور — مسیح — ابن مریم — کو بھی — حالانکہ — انہیں — صرف — ایک الٰہ کی عبادت — کا حکم دیا گیا تھا — اس — کے علاوہ کوئی الٰہ نہیں — پاک ہے وہ — ان — کی شرکت سے",
"""۱۔ احبار و رہبان — اللہ کے علاوہ — رب قرار دینا۔
۲۔ ’’اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَابًا مِّن دُونِ اللَّهِ وَالْمَسِيحَ ابْنَ مَرْيَمَ وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا إِلَٰهًا وَاحِدًا لَّا إِلَٰهَ إِلَّا هُوَ سُبْحَانَهُ عَمَّا يُشْرِكُونَ‘‘ — انہوں نے — اپنے — احبار و رہبان — کو — اللہ کے علاوہ — رب — بنا لیا — اور — مسیح — ابن مریم — کو بھی — حالانکہ — انہیں — صرف — ایک الٰہ کی عبادت — کا حکم دیا گیا تھا — اس — کے علاوہ کوئی الٰہ نہیں — پاک ہے وہ — ان — کی شرکت سے — یعنی یہود و نصاریٰ — اپنے — علماء کو — رب جیسا مقام — دیتے ہیں — اور — مسیح کو بھی — بیٹا — کہتے ہیں۔
۳۔ عملی سبق: عالم کو — رب کا درجہ مت دو؛ عبادت صرف اللہ کی ہے۔"""
),
1267: (
"وہ — چاہتے ہیں — کہ — اللہ کے نور — کو — اپنے منہ — سے — بجھا دیں — اور — اللہ — مانتا — ہے — مگر — اپنے نور — کو — مکمل — کرنا — اگرچہ — کافر ناپسند کریں",
"""۱۔ اللہ کا نور — جس کو کوئی نہیں بجھا سکتا۔
۲۔ ’’يُرِيدُونَ أَن يُطْفِئُوا نُورَ اللَّهِ بِأَفْوَاهِهِمْ وَيَأْبَى اللَّهُ إِلَّا أَن يُتِمَّ نُورَهُ وَلَوْ كَرِهَ الْكَافِرُونَ‘‘ — وہ — چاہتے ہیں — کہ — اللہ کے نور — کو — اپنے منہ — سے — بجھا دیں — اور — اللہ — مانتا — ہے — مگر — اپنے نور — کو — مکمل — کرنا — اگرچہ — کافر ناپسند کریں — یعنی کافر — اللہ کے نور کو — بجھانے کی کوشش کرتے ہیں — مگر اللہ — اسے مکمل کر کے ہی — رہتا ہے۔
۳۔ عملی سبق: اللہ کا نور — کوئی نہیں روک سکتا؛ آپ اس میں — شامل — ہو جائیں۔"""
),
1268: (
"وہی — ہے جس نے — اپنے رسولؐ کو — ہدایت اور حق کے دین — کے ساتھ — بھیجا — تاکہ — وہ — اسے — سارے دین — پر غالب کر دے — اگرچہ — مشرک ناپسند کریں",
"""۱۔ دین الحق کا غلبہ — اللہ کی ضمانت۔
۲۔ ’’هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَلَوْ كَرِهَ الْمُشْرِكُونَ‘‘ — وہی — ہے جس نے — اپنے رسولؐ کو — ہدایت اور حق کے دین — کے ساتھ — بھیجا — تاکہ — وہ — اسے — سارے دین — پر غالب کر دے — اگرچہ — مشرک ناپسند کریں — یعنی اللہ — اپنے دین کو — آخرکار — غالب — کروا کر ہی رہے گا۔
۳۔ عملی سبق: حق — آخرکار غالب ہوگا؛ ہمت مت ہارو۔"""
),
1269: (
"اے ایمان والو — بے شک — بہت سے احبار و رہبان — لوگوں کا مال — باطل — طریقے سے کھاتے ہیں — اور — اللہ کے راستے سے — روکتے ہیں — اور — جو لوگ — سونا چاندی — جمع کرتے ہیں — اور — اسے اللہ کی راہ میں — خرچ نہیں کرتے — انہیں — دردناک عذاب کی — خوش خبری سنا دو",
"""۱۔ مال جمع کرنا — بغیر زکوٰۃ — بڑا گناہ۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ كَثِيرًا مِّنَ الْأَحْبَارِ وَالرُّهْبَانِ لَيَأْكُلُونَ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَيَصُدُّونَ عَن سَبِيلِ اللَّهِ وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّۃَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ‘‘ — اے ایمان والو — بے شک — بہت سے احبار و رہبان — لوگوں کا مال — باطل — طریقے سے کھاتے ہیں — اور — اللہ کے راستے سے — روکتے ہیں — اور — جو لوگ — سونا چاندی — جمع کرتے ہیں — اور — اسے اللہ کی راہ میں — خرچ نہیں کرتے — انہیں — دردناک عذاب کی — خوش خبری سنا دو — یعنی مال جمع کرنا — بغیر زکوٰۃ — دردناک عذاب — کا سبب ہے؛ علماء کی باطل کمائی بھی — قابلِ مذمت ہے۔
۳۔ عملی سبق: خمس اور زکوٰۃ ادا کرو؛ مال کا ذخیرہ — عذاب ہے۔"""
),
1270: (
"جس دن — یہ — جہنم کی آگ — میں — گرم کیا جائے — پھر — اس — سے — ان — کی پیشانیاں — اور — ان کے پہلو — اور — ان کی پیٹھیں — داغی جائیں — یہ — وہ — مال ہے — جو تم نے اپنے لیے — جمع کیا تھا — پس — بنائے کو — چکھو — جو — تم — جمع کرتے تھے",
"""۱۔ کنزِ سونا چاندی — جس دن — داغ دیا جائے گا۔
۲۔ ’’يَوْمَ يُحْمَىٰ عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا مَا كُنتُمْ تَكْنِزُونَ‘‘ — جس دن — یہ — جہنم کی آگ — میں — گرم کیا جائے — پھر — اس — سے — ان — کی پیشانیاں — اور — ان کے پہلو — اور — ان کی پیٹھیں — داغی جائیں — یہ — وہ — مال ہے — جو تم نے اپنے لیے — جمع کیا تھا — پس — بڑے کو — چکھو — جو — تم — جمع کرتے تھے — یعنی جمع شدہ مال — جہنم میں — جلانے اور داغنے کے لیے — ہو گا۔
۳۔ عملی سبق: مال کا ذخیرہ — عذاب کا ذریعہ ہے؛ زکوٰۃ و نفقہ کرو۔"""
),
1271: (
"بے شک — مہینوں کی تعداد — اللہ — کے نزدیک — بارہ ماہ — ہے — اللہ کی کتاب میں — جس دن — اس نے آسمان اور زمین — بنائی — ان — میں سے — چار — ماہ — حرمت والے ہیں — یہی — سیدھا دین — ہے — پس — ان — میں — اپنی جانوں پر ظلم نہ کرو — اور — مشرکوں سے — سب — مل کر لڑو — جس طرح — وہ — سب — مل کر — تم سے لڑتے ہیں — اور — جان لو — کہ — اللہ — متقیوں کے ساتھ ہے",
"""۱۔ سال کے 12 ماہ — 4 حرمت والے۔
۲۔ ’’إِنَّ عِدَّۃَ الشُّهُورِ عِندَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ مِنْهَا أَرْبَعَۃٌ حُرُمٌ ذَٰلِكَ الدِّينُ الْقَيِّمُ فَلَا تَظْلِمُوا فِيهِنَّ أَنفُسَكُمْ وَقَاتِلُوا الْمُشْرِكِينَ كَافَّۃً كَمَا يُقَاتِلُونَكُمْ كَافَّۃً وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ‘‘ — بے شک — مہینوں کی تعداد — اللہ — کے نزدیک — بارہ ماہ — ہے — اللہ کی کتاب میں — جس دن — اس نے آسمان اور زمین — بنائی — ان — میں سے — چار — ماہ — حرمت والے ہیں — یہی — سیدھا دین — ہے — پس — ان — میں — اپنی جانوں پر ظلم نہ کرو — اور — مشرکوں سے — سب — مل کر لڑو — جس طرح — وہ — سب — مل کر — تم سے لڑتے ہیں — اور — جان لو — کہ — اللہ — متقیوں کے ساتھ ہے — یعنی 12 ماہ کا سال — اللہ کی کتاب میں — مقرر ہے؛ حرمت والے ماہ — خاص ہیں؛ ان میں — ظلم نہیں کرنا۔
۳۔ عملی سبق: اسلامی کیلنڈر — اللہ کی کتاب کا — حصہ ہے؛ ان حرمت والے مہینوں میں — ظلم سے بچو۔"""
),
1272: (
"نسيء — کفر میں — اضافہ ہے — اس سے — وہ — لوگ — جو — کفر کرتے ہیں — گمراہ ہوتے ہیں — وہ — اسے — ایک سال حلال کرتے ہیں — اور — ایک سال حرام — تاکہ — وہ — برابر کریں — جو — اللہ — نے حرام کیا — پس — وہ — ان — کی بری عبادت کو اچھا دکھاتے ہیں — اور — اللہ — کافروں کو — ہدایت نہیں دیتا",
"""۱۔ نسيء — حرمت والے مہینوں کو — پس و پیش کرنا — کفر میں اضافہ۔
۲۔ ’’إِنَّمَا النَّسِيءُ زِيَادَۃٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا لِّيُوَاطِئُوا عِدَّۃَ مَا حَرَّمَ اللَّهُ فَيُحِلُّوا مَا حَرَّمَ اللَّهُ زُيِّنَ لَهُمْ سُوءُ أَعْمَالِهِمْ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ‘‘ — نسيء — کفر میں — اضافہ ہے — اس سے — وہ — لوگ — جو — کفر کرتے ہیں — گمراہ ہوتے ہیں — وہ — اسے — ایک سال حلال کرتے ہیں — اور — ایک سال حرام — تاکہ — وہ — برابر کریں — جو — اللہ — نے حرام کیا — پس — وہ — ان — کی بری عبادت کو اچھا دکھاتے ہیں — اور — اللہ — کافروں کو — ہدایت نہیں دیتا — یعنی مشرک — حرمت والے مہینوں — کو — اپنی مرضی سے — تبدیل کرتے تھے — یہ — کفر میں اضافہ — ہے۔
۳۔ عملی سبق: اللہ کے احکام — کوئی تبدیلی نہیں مانگتے؛ پورے ایمان کے ساتھ — مانو۔"""
),
1273: (
"اے ایمان والو — تمہیں کیا ہوا — کہ — جب — تمہیں کہا گیا — اللہ کی راہ میں — نکل جاؤ — تو — تم — زمین — پر — بوجھل ہو گئے — کیا — تم — آخرت کے مقابلے میں — دنیا کی زندگی سے — خوش ہو گئے — پس — دنیا کی زندگی — کی — آخرت میں — متاع — تھوڑی ہے",
"""۱۔ جہاد سے سستی — دنیا کی محبت کا نتیجہ۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا مَا لَكُمْ إِذَا قِيلَ لَكُمُ انفِرُوا فِي سَبِيلِ اللَّهِ اثَّاقَلْتُمْ إِلَى الْأَرْضِ أَرَضِيتُم بِالْحَيَاۃِ الدُّنْيَا مِنَ الْآخِرَۃِ فَمَا مَتَاعُ الْحَيَاۃِ الدُّنْيَا فِي الْآخِرَۃِ إِلَّا قَلِيلٌ‘‘ — اے ایمان والو — تمہیں کیا ہوا — کہ — جب — تمہیں کہا گیا — اللہ کی راہ میں — نکل جاؤ — تو — تم — زمین — پر — بوجھل ہو گئے — کیا — تم — آخرت کے مقابلے میں — دنیا کی زندگی سے — خوش ہو گئے — پس — دنیا کی زندگی — کی — آخرت میں — متاع — تھوڑی ہے — یعنی جہاد سے سستی — دنیا کی محبت کا نتیجہ ہے؛ آخرت — زیادہ — ضروری ہے۔
۳۔ عملی سبق: دنیا کی زندگی — آخرت کے مقابلے میں — تھوڑی ہے۔"""
),
1274: (
"اگر — تم — نکلے نہیں — تو — وہ — تمہیں — دردناک عذاب — دے گا — اور — تمہاری جگہ — دوسری قوم — لے آئے گا — اور — تم — اللہ کو — کچھ — نقصان نہیں پہنچا سکتے — اور — اللہ — ہر چیز پر — قادر ہے",
"""۱۔ جہاد نہ کرنے کی سزا — عذاب اور تبدیلیِ قوم۔
۲۔ ’’إِلَّا تَنفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْئًا وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اگر — تم — نکلے نہیں — تو — وہ — تمہیں — دردناک عذاب — دے گا — اور — تمہاری جگہ — دوسری قوم — لے آئے گا — اور — تم — اللہ کو — کچھ — نقصان نہیں پہنچا سکتے — اور — اللہ — ہر چیز پر — قادر ہے — یعنی جہاد سے سستی — عذاب — اور — تبدیلی قوم — کا سبب ہے۔
۳۔ عملی سبق: اللہ — کسی کی محتاجگی نہیں؛ جہاد — آپ کی ذمہ داری ہے۔"""
),
1275: (
"اگر — تم — اس کی مدد نہ کرو — تو — بے شک — اللہ — نے — اس کی مدد کی — جب — اسے — کافروں نے — نکالا — وہ — دو میں سے دوسرا تھا — جب — وہ — دونوں — غار میں تھے — جب — وہ — اپنے ساتھی سے کہتا ہے — غمگین نہ ہو — بے شک — اللہ — ہمارے ساتھ ہے — پس — اللہ — نے — اس پر — اپنا سکون — اتارا — اور — اس کی مدد — ایسے لشکروں سے — کی — جو تمہیں نظر نہیں آتے — اور — کافروں کا کلمہ — نیچے کر دیا — اور — اللہ کا کلمہ — ہی — بلند ہے — اور — اللہ — زبردست حکمت والا ہے",
"""۱۔ ہجرت کے موقع پر — غارِ ثور — اللہ کی مدد۔
۲۔ ’’إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا فَأَنزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَۃَ الَّذِينَ كَفَرُوا السُّفْلَىٰ وَكَلِمَۃُ اللَّهِ هِيَ الْعُلْيَا وَاللَّهُ عَزِيزٌ حَكِيمٌ‘‘ — اگر — تم — اس کی مدد نہ کرو — تو — بے شک — اللہ — نے — اس کی مدد کی — جب — اسے — کافروں نے — نکالا — وہ — دو میں سے دوسرا تھا — جب — وہ — دونوں — غار میں تھے — جب — وہ — اپنے ساتھی سے کہتا ہے — غمگین نہ ہو — بے شک — اللہ — ہمارے ساتھ ہے — پس — اللہ — نے — اس پر — اپنا سکون — اتارا — اور — اس کی مدد — ایسے لشکروں سے — کی — جو تمہیں نظر نہیں آتے — اور — کافروں کا کلمہ — نیچے کر دیا — اور — اللہ کا کلمہ — ہی — بلند ہے — اور — اللہ — زبردست حکمت والا ہے — یعنی غارِ ثور میں — اللہ نے — نبیؐ کی مدد کی — ان کے ساتھی ابوبکر تھے — مگر اصل مدد — اللہ کی تھی۔
۳۔ عملی سبق: اللہ — ہر حال میں — اپنے نبیؐ کا ساتھ دیتا ہے۔"""
),
}
